style.css:
@-moz-document domain("avito.ru") {
:root {
    color-scheme: dark;

    --av-bg: #14181d;          /* base canvas */
    --av-surface: #1c2128;     /* elevated cards */
    --av-surface-2: #1a1f26;   /* secondary surface */
    --av-header: #0d1117;      /* header / footer */
    --av-border: #2a313a;      /* subtle borders */
    --av-text: #e6edf3;        /* primary text */
    --av-text-soft: #c4cdd6;   /* body text */
    --av-text-muted: #8b949e;  /* muted / placeholder */
    --av-accent: #4aa8ff;      /* refined Avito blue */
    --av-accent-hover: #7cc4ff;
  }

  /* ---- Base canvas ---- */
  html {
    background-color: var(--av-bg) !important;
  }
  body {
    background-color: var(--av-bg) !important;
    color: var(--av-text-soft) !important;
  }

  /* ---- Borders ---- */
  /* Soften every light border to a subtle dark one (colour only — this never
     adds a border, so it is safe to apply universally). */
  *, *::before, *::after {
    border-color: var(--av-border) !important;
  }

  /* Avito's class names are hashed and unstable, and white/light-grey fills are
     painted on hundreds of nested block wrappers. The robust lever is to make
     structural block elements transparent so the dark canvas shows through,
     then deliberately re-paint the real surfaces (header, cards, inputs,
     coloured badges) in the rules below. Inline elements that carry brand
     colours (badges, buttons) are re-painted afterwards and keep their fill.
     `label` is included because Avito wraps several inputs (mortgage-calculator
     value fields, the login/auth form fields) in a `<label>` that carries a
     hard-coded white field background while the inner <input> is already dark —
     neutralising the wrapper lets the dark input show; button-style labels are
     re-painted to a surface by the button rules below.

     `span` is deliberately NOT in this list. Avito paints its data-driven fills
     on inline SPANs: the colour-filter swatches (`color-circle-circle`, whose
     hue arrives as an inline `background: rgb(...)` straight from the API) and
     the current-page pagination pill. Flattening every span erased all of them —
     a "Цвет" filter with no circles at all. Across home / search / item /
     profile exactly ONE span carries a light fill (the seller-avatar
     placeholder), and it is re-painted explicitly below. */
  div, section, article, main, aside, ul, ol, li, dl, dd, dt,
  table, tbody, thead, tr, td, th, figure, fieldset, label {
    background-color: transparent !important;
  }
  /* The one light SPAN the neutraliser used to cover: the avatar placeholder
     (#f2f1f0) behind a seller logo on brand/profile pages. Avito renamed the
     wrapper from `UserInfo-module-avatar` to `AvatarNameView-module-avatar`, and
     the placeholder grew to 120×120 — a glaring white disc on every profile whose
     seller has no logo. Both names are matched so either build is covered.
     The reviews list on a seller profile repeats the pattern a third time
     (`styles-module-avatar` around a 40×40 span), 25 to a page — covered by a photo
     once it loads, glaring white while it does not. Matching the shared
     `…-module-avatar` fragment covers every build's spelling of the wrapper. */
  [class*="-module-avatar"] span {
    background-color: var(--av-surface) !important;
  }
  /* The "Показать все" badge row ends with a 28×28 `…ShowAllButton-module-circle`
     holding a mask-image "⋯" glyph. The circle keeps a hard `#f2f1f0`, and the broad
     text rule lightened the glyph that used to be dark on it — so the dots sat at
     ~1.4:1 on a disc that was itself the brightest thing in the sidebar. Sinking the
     disc to the elevated surface restores the contrast the light glyph needs. */
  [class*="ShowAllButton-module-circle"] {
    background-color: var(--av-surface) !important;
  }

  /* Stories rail. The unread ring around each 98×98 story avatar is a 2px border
     in Avito's status red `#ff6163` — the ONLY thing marking a story as unseen —
     and the blanket border reset above collapsed it to the generic line colour, so
     every story looked already watched. Native hue kept: it clears 4.5:1 on the
     dark canvas and is the same red the theme keeps for seller status. */
  [class*="preview-item-bordered"] {
    border-color: #ff6163 !important;
  }

  /* Header bar */
  [data-marker="header/navbar"],
  header {
    background-color: var(--av-header) !important;
    border-color: var(--av-border) !important;
  }
  /* The site chrome's navbar is a DIV (`header/navbar`); the only real <header>
     elements are the ones INSIDE popups and cards, so the rule above painted a
     near-black title bar across every modal (a hard seam against the modal's
     elevated surface). Let those inherit the panel they sit on. */
  [data-marker$="/popup-header"] {
    background-color: transparent !important;
  }
  /* The other half of that same over-reach: Avito builds every listing card's
     PHOTO FRAME out of a semantic `<header class="styles-picture-…">`, so the rule
     above painted 55 near-black slabs behind the photos on the home grid (natively
     transparent). Invisible while a `object-fit:cover` photo covers the frame, but
     it is the frame that shows during lazy-load, behind transparent PNGs and in
     any letterboxed gap. The bare `header` arm must stay — the legacy 404/error
     template uses a real `<header class="header">` for its page chrome. */
  header[class*="styles-picture"] {
    background-color: transparent !important;
  }
  /* Same over-reach, third variant: a seller profile lists its reviews as cards whose
     name/date row is a semantic `<header data-marker="review(N)/header">`, natively
     transparent — so the rule stamped a near-black 553×40 band across the top of all
     25 reviews while the review body sat on the canvas. Every `<header>` Avito ships
     with a marker is a COMPONENT header (review, popup, card) rather than page chrome;
     the legacy 404/error template's `<header class="header">`, which the bare arm
     exists for, carries no marker. */
  header[data-marker] {
    background-color: transparent !important;
  }

  /* Sticky-on-scroll header + sort/filter toolbar (search results). These are
     hashed-class wrapper DIVs (not the <header> element), so the neutraliser
     flattened them to transparent and scrolled results bled through as they
     pinned to the top. Re-establish a solid opaque bar on each sticky variant. */
  [class*="stickyHeader"] {
    background-color: var(--av-header) !important;
    border-color: var(--av-border) !important;
  }
  /* The results page's sort / "Уведомлять о новых" bar is a `position:sticky` DIV
     whose own fill is a hard `background-color: #fff`. Avito renamed it from
     `…topPanelSticked` to `index-topPanel` (+ `…Hidden` / `…Static` /
     `…StickyFiltersDesktop` state classes), so the old `topPanelStick` hook matched
     nothing and the neutraliser left the bar transparent: scrolled cards ran
     straight through the sort control and the subscribe link. Matching the whole
     `topPanel` family covers both spellings. The fill is the CANVAS tone, not an
     elevated one — natively the bar is the same white as the page behind it, so a
     surface-coloured band would invent a stripe that is not there while the bar
     sits in flow. */
  [class*="topPanel"] {
    background-color: var(--av-bg) !important;
    border-color: var(--av-border) !important;
  }
  /* The item page's `position:fixed` title bar (thumbnail, price, title, favourite +
     delivery/phone/message CTAs) is a natively WHITE viewport-wide 48px strip; without a
     fill the description and the right-hand ad banner scroll straight through it.
     The bar itself is unreachable, but it carries a `transform`, which makes it the
     containing block for `position:fixed` descendants — so a fixed pseudo hung on a
     node inside it anchors to the bar's own box. The hook is the bar's favourite
     button scoped to `.js-item-view-title-info` (the one non-hash class on the
     ancestor chain): the same marker also names the buy-box heart, and only the bar's
     copy sits inside that wrapper.
     Which node hosts the pseudo is load-bearing, not arbitrary. `z-index:-1` resolves
     inside the nearest STACKING CONTEXT, and the bar's price container is
     `position:relative; z-index:15` — a pseudo hung there paints above every sibling in
     the bar and hides the title, thumbnail and CTAs behind the strip. The favourite
     button is `position:relative; z-index:auto`, so it creates no context and the strip
     lands in the bar's own negative layer, behind all of the bar's content.
     The bar is `opacity:0` and translated off-screen while parked, so nothing shows at
     scroll 0. The height is stated explicitly rather than as `bottom:0`: should Avito
     drop the transform, the pseudo falls back to a viewport-anchored 48px strip in the
     same place instead of a full-screen slab. */
  .js-item-view-title-info [data-marker="item-view/favorite-button"]::before {
    content: "";
    position: fixed;
    top: 0;
    height: 48px;
    left: 0;
    right: 0;
    z-index: -1;
    background-color: var(--av-header) !important;
  }

  /* Avito logo wordmark — the "Avito" lettering is a second SVG whose single
     path has NO fill attribute, so it defaults to solid black and vanishes on
     the dark header (the colourful dot paths DO carry fill attrs and keep their
     brand colours). Light only the attribute-less wordmark path. The header
     logo also appears in a hashed-class variant (error/404, some entry pages)
     where NO `index-logo`/`Logo-module` class is present — there the only stable
     hook is the home-link anchor (`a[href="/"]`) wrapping the wordmark svg. The
     `:not([fill])` guard keeps this scoped to the attribute-less wordmark path
     and never touches the coloured dots (which carry fill attrs). The generic
     error/maintenance template ("Сайт временно недоступен", 5xx) ships the
     wordmark as a bare `<svg viewBox="0 0 79 30">` inside build-hashed spans —
     no class, no home-link, no marker — so none of the hooks above reach it and
     its single fill-less path renders solid black (invisible on the dark canvas).
     The wordmark's fixed brand viewBox is the stable hook. */
  [class*="index-logo"] svg path:not([fill]),
  [class*="Logo-module"] svg path:not([fill]),
  a[href="/"] svg path:not([fill]),
  svg[viewBox="0 0 79 30"] path:not([fill]) {
    fill: var(--av-text) !important;
  }

  /* Top notification banner ("how to keep using Avito on iOS", etc.) and the
     full-width home hero-promo (`top-notification/hero-banner-main-page/…`).
     The hero variant paints a light lavender→pink gradient as background-IMAGE,
     which layers over any background-color — background-image must be cleared
     too. The banner's 3D illustration is a separate child <img>, untouched. */
  [data-marker^="top-notification"],
  [data-marker^="top-banner"] {
    background-color: var(--av-surface-2) !important;
    background-image: none !important;
    border-color: var(--av-border) !important;
  }

  /* ---- Inline-styled badges & pills ---- */
  /* These carry their fill via an inline `background` (so the neutraliser above
     would otherwise flatten the DIVs). Re-paint them, refining each saturated
     brand colour to a tone that sits well on the dark canvas while staying
     instantly recognisable. */

  /* NOTE ON CASE: Avito writes these inline styles as UPPERCASE hex
     (`background-color:#02D15C`). Attribute substring matching is
     case-SENSITIVE, and the case-insensitive `i` flag is rejected by the
     userstyles.org parser — so every literal must be listed in the exact case
     the site emits. Without the uppercase variants the neutraliser wins and the
     badges lose their fill entirely (grey text floating over the photo). */

  /* Ribbon end-caps, hex form. Avito serialises the cap's inline colour as hex
     on some pages and as `rgb()` on others, so both must be covered; the cap
     must take the SAME refined tone as the pill body or it reads as a mismatched
     wedge. Must precede the pill rules: "background-color:#02D15C" CONTAINS the
     substring "color:#02D15C", so the pill rules below re-override the label. */
  [style*="color:#02D15C"], [style*="color:#02d15c"] {
    color: #198049 !important;
  }
  [style*="color:#965EEB"], [style*="color:#965eeb"] {
    color: #7d5bc4 !important;
  }
  [style*="color:#FF4053"], [style*="color:#ff4053"] {
    color: #c8323f !important;
  }
  [style*="color:#00AAFF"], [style*="color:#00aaff"] {
    color: var(--av-accent) !important;
  }
  [style*="color:#CCECFF"], [style*="color:#ccecff"],
  [style*="color:#CFEDFF"], [style*="color:#cfedff"],
  [style*="color: rgb(204, 236, 255)"], [style*="color:rgb(204, 236, 255)"],
  [style*="color: rgb(207, 237, 255)"], [style*="color:rgb(207, 237, 255)"] {
    color: #1d2c3a !important;
  }
  /* The DISCOUNT ribbon ("Скидка"): body is an inline `background-color:#E50965`
     (Avito's discount crimson), cap is an inline `color:#E50965` on an SVG path
     filled with `currentColor`. Neither form was covered, so the div-neutraliser
     wiped the pill body and the broad text rule greyed both caps — the badge read
     as bare text between two pale wedges, straight on the listing photo. Refined
     to #c41f66 (5.6:1 against the white label), matching how the other saturated
     brand fills are toned down. */
  [style*="color:#E50965"], [style*="color:#e50965"],
  [style*="color: rgb(229, 9, 101)"], [style*="color:rgb(229, 9, 101)"] {
    color: #c41f66 !important;
  }
  /* The item page's stock line ("В наличии: несколько") wraps its QUANTITY in a span
     carrying an inline `color: rgb(0, 194, 87)` — Avito's in-stock green, and the only
     thing separating the quantity from the "В наличии:" label beside it. The broad text
     rule's `!important` reaches it, so the inline value needs restating; native #00c257
     clears 7:1 on the dark surfaces, so keep the exact hue. Listed with the cap rules
     rather than in the text block below because "background-color:#00C257" contains the
     substring "color:#00C257" — anything painting that fill must be able to re-override
     this label colour, and only a rule LATER in source order can.
     The descendant arm is required, not defensive: the coloured span wraps a second,
     un-coloured span that holds the actual text node, and the broad rule reaches that
     one through its own `span` match rather than through inheritance. */
  [style*="color: rgb(0, 194, 87)"], [style*="color: rgb(0, 194, 87)"] *,
  [style*="color:rgb(0, 194, 87)"], [style*="color:rgb(0, 194, 87)"] *,
  [style*="color:#00C257"], [style*="color:#00C257"] *,
  [style*="color:#00c257"], [style*="color:#00c257"] * {
    color: #00c257 !important;
  }
  /* The NEUTRAL ribbon ("Скидка на доставку", "14 дней на возврат", "Рассрочка"):
     body is an inline `background-color:#EBEAE8`, cap is an inline `color:#EBEAE8`
     on an SVG path filled with `currentColor`. The div-neutraliser wiped the body
     and the broad text rule repainted the cap `--av-text-soft`, leaving two pale
     wedges floating on either side of a bodiless label. */
  [style*="color:#EBEAE8"], [style*="color:#ebeae8"],
  [style*="color: rgb(235, 234, 232)"], [style*="color:rgb(235, 234, 232)"] {
    color: var(--av-surface) !important;
  }

  /* CRITICAL: these selectors match inline `background-color:` ONLY. A bare
     `[style*="rgb(2, 209, 92)"]` also matches the ribbon END-CAPS, whose inline
     is `color: rgb(2, 209, 92)` and whose pointed tail is an SVG path filled
     with `currentColor` — painting those a solid rectangle AND flipping the
     tail white (white wedges on both ends of every green badge). */

  /* Light-blue info pills ("trusted seller", "documents verified", …) — the
     biggest light surface on search. Move to a muted blue-tinted dark chip. */
  [style*="background-color: rgb(204, 236, 255)"],
  [style*="background-color:rgb(204, 236, 255)"],
  [style*="background-color: rgb(207, 237, 255)"],
  [style*="background-color:rgb(207, 237, 255)"],
  [style*="background-color:#ccecff"], [style*="background-color:#CCECFF"],
  [style*="background-color:#cfedff"], [style*="background-color:#CFEDFF"] {
    background-color: #1d2c3a !important;
    color: #9fd0f5 !important;
  }

  /* Sale / discount (red) */
  [style*="background-color: rgb(255, 64, 83)"],
  [style*="background-color:rgb(255, 64, 83)"],
  [style*="background-color:#ff4053"], [style*="background-color:#FF4053"] {
    background-color: #c8323f !important; color: #fff !important;
  }
  /* Below-market / delivery discount (green) */
  [style*="background-color: rgb(2, 209, 92)"],
  [style*="background-color:rgb(2, 209, 92)"],
  [style*="background-color:#02d15c"], [style*="background-color:#02D15C"] {
    background-color: #198049 !important; color: #fff !important;
  }
  /* Avito Guarantee / promo (purple) */
  [style*="background-color: rgb(150, 94, 235)"],
  [style*="background-color:rgb(150, 94, 235)"],
  [style*="background-color:#965eeb"], [style*="background-color:#965EEB"] {
    background-color: #7d5bc4 !important; color: #fff !important;
  }
  /* Installment / other brand-blue inline pills */
  [style*="background-color: rgb(0, 170, 255)"],
  [style*="background-color:rgb(0, 170, 255)"],
  [style*="background-color:#00aaff"], [style*="background-color:#00AAFF"] {
    background-color: var(--av-accent) !important; color: #0b1620 !important;
  }
  /* Model-score badge in the item page's FIXED title bar. The buy-box copy is
     reached through `rating-and-reviews` below, but the bar's copy sits under pure
     build hashes — its only durable hook is the inline fill, written with the
     `background` SHORTHAND (`background: rgb(0, 194, 87)`), which a
     `background-color:` selector cannot see. Without it the div-neutraliser left a
     bare grey "4,8" where a green score pill belongs. Same refined green as the
     buy-box pill. */
  [style*="background: rgb(0, 194, 87)"],
  [style*="background:rgb(0, 194, 87)"],
  [style*="background:#00C257"], [style*="background:#00c257"] {
    background-color: #198049 !important;
  }
  [style*="background: rgb(0, 194, 87)"],
  [style*="background: rgb(0, 194, 87)"] *,
  [style*="background:rgb(0, 194, 87)"],
  [style*="background:rgb(0, 194, 87)"] *,
  [style*="background:#00C257"], [style*="background:#00C257"] *,
  [style*="background:#00c257"], [style*="background:#00c257"] * {
    color: #fff !important;
  }
  /* Discount ribbon body (crimson) — same ordering constraint as the neutral one
     below: "background-color:#E50965" CONTAINS "color:#E50965", so the cap rule
     must come first and this must re-override the label. */
  [style*="background-color:#E50965"], [style*="background-color:#e50965"],
  [style*="background-color: rgb(229, 9, 101)"],
  [style*="background-color:rgb(229, 9, 101)"] {
    background-color: #c41f66 !important; color: #fff !important;
  }
  /* Neutral ribbon body — must come after the `color:#EBEAE8` cap rule above,
     because "background-color:#EBEAE8" CONTAINS the substring "color:#EBEAE8".
     Avito emits the inline value as raw hex on a server-rendered page and as
     `rgb(...)` once React re-renders the list client-side (any filter change,
     category click or sort), so both spellings must be listed. */
  [style*="background-color:#EBEAE8"], [style*="background-color:#ebeae8"],
  [style*="background-color: rgb(235, 234, 232)"],
  [style*="background-color:rgb(235, 234, 232)"] {
    background-color: var(--av-surface) !important;
    color: var(--av-text-soft) !important;
  }

  /* Ribbon end-caps. Their inline is `color: rgb(<brand>)`; the tail is an SVG
     path with `fill: currentColor`, so the cap must take the SAME refined tone
     as the pill body above or it reads as a coloured/white wedge. */
  [style*="color: rgb(2, 209, 92)"], [style*="color: rgb(2, 209, 92)"] *,
  [style*="color:rgb(2, 209, 92)"], [style*="color:rgb(2, 209, 92)"] * {
    color: #198049 !important;
  }
  [style*="color: rgb(150, 94, 235)"], [style*="color: rgb(150, 94, 235)"] *,
  [style*="color:rgb(150, 94, 235)"], [style*="color:rgb(150, 94, 235)"] * {
    color: #7d5bc4 !important;
  }
  [style*="color: rgb(255, 64, 83)"], [style*="color: rgb(255, 64, 83)"] *,
  [style*="color:rgb(255, 64, 83)"], [style*="color:rgb(255, 64, 83)"] * {
    color: #c8323f !important;
  }
  [style*="color: rgb(0, 170, 255)"], [style*="color: rgb(0, 170, 255)"] *,
  [style*="color:rgb(0, 170, 255)"], [style*="color:rgb(0, 170, 255)"] * {
    color: var(--av-accent) !important;
  }

  /* ---- Buttons ---- */
  /* Avito reuses one hashed Button class for both primary (blue) and secondary
     (light-grey) buttons, so the class can't tell them apart. Give every button
     an elevated dark surface by default, then promote only the real primary
     CTAs to brand blue by their stable data-marker.

     One arm must stay narrow or plain TEXT links get a button surface — a grey
     box hugging the words. `[data-marker$="/link"]` also caught `seller-link/link`
     (the seller name — a transparent text link); only the `*-button/link` markers
     (e.g. `messenger-button/link`, natively a filled `#f2f1f0`/brand-blue CTA)
     are real buttons needing the dark repaint.

     `[role="button"]` is NOT matched here. Avito hangs that role on whole
     carousel SLIDES (`SliderGallery-module-carousel-children`, 849×192 on a
     brand page) and on individual rating STARS, so the rule painted an
     `--av-surface` slab straight across the profile's promo banner. Every
     `[role="button"]` element the site ships is natively transparent — the ⋯
     card action, the star row, the "Ещё" reference — so none of them needs a
     surface at all.

     `[data-marker$="-button"]` is left broad on purpose: adding `:not(a)` there
     would raise it to specificity (0,1,1) and it would then beat the (0,1,0)
     brand-blue CTA rule below, turning "Найти" grey. The anchors it over-reaches
     are un-painted by the separate rule that follows instead. */
  button,
  a[class*="styles-module-root"], label[class*="styles-module-root"],
  [class*="multiselect-outline-input"], [class*="style-module-wrapper"],
  [data-marker$="-button"], [data-marker$="-button/link"],
  [data-marker="icebreakers"], [data-marker="icebreakers"] > * {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* Avito also hangs the `-button` marker on plain text LINKS — `header/login-button`
     ("Вход и регистрация"), `item-specification-button` ("Все характеристики") and
     `expandable-button` ("Ещё 17") are all natively transparent `<a>`s, and the rule
     above boxed each one in a grey slab. Every `-button` element that truly carries a
     light fill (`item-view/favorite-button`, `item-view/abuse-button`: `#f2f1f0`) and
     every brand-blue CTA ("Найти", both phone buttons) is a real `<button>`, so no
     anchor here needs a surface. Anchor CTAs are painted via the `-button/link` and
     `styles-module-root` arms, whose markers don't end in `-button`. */
  a[data-marker$="-button"] {
    background-color: transparent !important;
  }
  /* Same over-reach on the DIV side, where the `-button` marker names a hit ZONE
     rather than a control: the item gallery's 50×456 prev/next strips
     (`image-frame/left-button`, `…/right-button`) became two grey columns flanking
     every photo, and `item-map-button` ("Узнать подробности") is a plain text link
     that ended up in a grey slab. Every div carrying the marker is natively
     transparent, and the div-neutraliser has already flattened them, so removing
     the fill only returns them to the dark canvas — it can never leak a light
     surface. The recommendation carousels' scroll arrows are the same shape of
     hit zone but ship as real `<button>`s, so they need naming too: a 36×302
     `--av-surface` bar was covering the card it floats over.
     The marker belongs to the CALL SITE, not to the control: the `/all/<category>`
     hubs' top-sellers rail ships the identical scroll button with `data-marker`
     absent and only its hashed module class (`styles-module-scrollButton-<hash>`)
     to name it, so the class hook is required alongside the markers. Every
     instance of it, on every page family, is natively transparent. */
  div[data-marker$="-button"],
  [data-marker$="/scroll-button-back"],
  [data-marker$="/scroll-button-forward"],
  button[class*="styles-module-scrollButton"] {
    background-color: transparent !important;
  }
  /* And on the LIST side: the results pagination is a `<ul data-marker="pagination-button">`
     wrapping one `<li>` per page, so the `-button` suffix matched the whole strip and
     boxed pages 1–30 plus both arrows in a 365×36 square-cornered grey slab that the
     site never draws (the `<ul>` is natively transparent; only the current-page pill
     carries a fill). The current-page rule further down is (0,2,0) on the page element
     itself, so un-painting the list cannot touch the indicator. */
  ul[data-marker$="-button"] {
    background-color: transparent !important;
  }
  /* Its prev/next arrows are real `<button>`s with no marker of their own, natively
     transparent like the page numbers around them. The generic button surface gave
     the (disabled) "previous" arrow a filled pill while the live page numbers stayed
     flat — reading as the selected item. Only the current page may carry a fill. */
  [data-marker="pagination-button"] button {
    background-color: transparent !important;
  }
  /* Design-system CHECKBOX and SWITCH labels — the filter rail's option rows
     (`params[N]/checkbox/M`) and the results toolbar's "Сначала из Москвы"
     (`filters/localPriority/localPriority`). Both are
     `<label class="styles-module-root-… styles-module-root_preset_default-…">`, which the
     button rule's `label[class*="styles-module-root"]` arm also matches — but natively
     they paint nothing (the class only declares a hover TOKEN), so a fill reads as a
     pre-selected row / an active chip. The Input-component labels that arm exists for
     (`price-from`, `price-to`, `search-form/suggest`) carry `root_size-*` / `root_empty`
     / `root_preset_overlay` instead, never `root_preset_default`.
     The trailing hyphen is the discriminator: the DS emits `root_preset_default-<hash>`
     for this label and `root_preset_default_priority_primary-<hash>` for the Button, so
     `root_preset_default-` excludes the Button preset exactly. Same specificity (0,1,1)
     as the button arm, so source order is what un-paints these. */
  label[data-marker*="/checkbox/"],
  label[class*="styles-module-root_preset_default-"] {
    background-color: transparent !important;
  }
  /* The item gallery's prev/next chevrons. The 50×456 hit ZONES are un-painted above,
     but each one holds a real 13×19 `<button>` that the generic rule then boxed: two
     small dark tiles sitting on the photo where the site draws a bare white chevron.
     The whole `image-frame/` family is overlay chrome on top of the picture — none of
     it may carry a surface. The fullscreen lightbox repeats the pattern one prefix
     over (`extended-gallery-frame/control-left|right`); its buy CTAs live under
     `gallery-delivery-button` / `item-phone-button/gallery`, outside this prefix, so
     they keep the fills their own rules give them. */
  [data-marker^="image-frame/"] button,
  [data-marker^="extended-gallery-frame/"] button {
    background-color: transparent !important;
  }
  /* The buy-box heart is natively bare, so the generic `-button` surface gave it a
     44px grey disc the site never draws. The FIXED title bar ships the same marker on
     its own copy, and that one IS a light `#f2f1f0` chip — `.js-item-view-title-info`
     is the one non-hash class separating them, and that copy also hosts the bar's
     background pseudo, so it must keep a fill. */
  [data-marker="item-view/favorite-button"] {
    background-color: transparent !important;
  }
  .js-item-view-title-info [data-marker="item-view/favorite-button"] {
    background-color: var(--av-surface) !important;
  }
  /* Seller-profile badge rows ("Данные подтверждены", "Компания проверена", …) and the
     "Показать все" row below them are `<button>`s laid out as bare icon+label lines —
     natively transparent, and only 230px wide while their labels run longer. The
     generic surface turned each into a grey pill that the label overflows, so the
     sidebar read as four ragged, clipped chips. */
  [data-marker^="badge-row-"],
  [data-marker="badge-show-all"] {
    background-color: transparent !important;
  }
  /* Profile photo carousel: its scroll arrows are 16×156 `<button>`s that float ON the
     photo strip (the site pairs each with a transparent `…arrow-cover` fade). The
     generic surface turned them into two grey bands slicing a column out of the
     end photos. Same shape of over-reach as the `scroll-button-*` bars above, under a
     different component's class. */
  [class*="Carousel-module-arrow"] {
    background-color: transparent !important;
  }
  /* Avito's design-system LINK component shares the `styles-module-root-…` class
     prefix with its Button component, so the arm above boxed every plain link in a
     grey slab — including all 91 listing-card titles on the home grid, which then
     read as filled chips instead of text. The Link's own modifier class
     (`root_underlineOffset_size-*`) is present on links and never on buttons, and
     every element carrying it is natively transparent. Same specificity as the
     button arm, so source order un-paints them. */
  a[class*="root_underlineOffset"] {
    background-color: transparent !important;
  }
  /* Avito's design-system Button encodes its hierarchy in the preset/priority
     modifier class: PRIMARY is a near-black `#141414` fill with a white label,
     secondary is a light `#f2f1f0` fill. The generic button rule above painted
     both `--av-surface`, so the two priorities became indistinguishable — and
     inside a floating panel, whose own fill is also `--av-surface`, BOTH read as
     bare text with no button shape at all (the region tooltip's "Изменить" /
     "Оставить так"). Promote the primary priority to the accent, matching every
     other brand CTA, and raise the secondary to a surface that separates from
     both the canvas and an elevated panel. The marker-specific rules that follow
     are later in source order, so per-CTA tuning still wins.

     The primary arm is scoped to `button`: Avito hangs the same preset on the
     search page's 20 SEO tag ANCHORS ("Популярные запросы"), which are chips
     rather than CTAs — and an anchor is already claimed by the (0,1,1)
     `a[class*="styles-module-root"]` arm above, so a (0,1,0) primary rule would
     win the label but lose the fill and leave dark text on the grey chip. */
  button[class*="root_preset_default_priority_primary"],
  button[class*="root_preset_primary"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  button[class*="root_preset_default_priority_primary"],
  button[class*="root_preset_default_priority_primary"] *,
  button[class*="root_preset_primary"],
  button[class*="root_preset_primary"] * {
    color: #0b1620 !important;
  }
  [class*="root_preset_secondary"] {
    background-color: #262c35 !important;
  }
  /* `root_preset_overlay` is the DS's float-over-imagery button: a solid WHITE pill the
     site uses on banners and photos. The generic surface sank it to the same tone as the
     panels it sits on (promo strips, hover cards), so it lost its button shape entirely.
     The secondary tone separates from both the canvas and an elevated panel. */
  [class*="root_preset_overlay"] {
    background-color: #262c35 !important;
  }
  /* `root_preset_accent` is the DS's OTHER solid primary — Avito's brand blue
     `#00AAFF` with a white label. Three of its instances already reach the accent
     through their own markers ("Найти", "Все категории"), but the region picker's
     main CTA ("Показать больше N объявлений") carries no marker, so it fell through
     to the generic dark `button` surface — `--av-surface` on a modal whose own panel
     is also `--av-surface`, i.e. the dialog's only action rendered as bare white text
     with no button shape at all. The trailing hyphen is load-bearing: the DS emits
     `root_preset_accent-<hash>`, so `root_preset_accent-` excludes the soft-blue
     `root_preset_accentSecondary-…` that the block below re-tunes. Written to fail
     SAFE: a build that drops the hash suffix simply restores today's grey. Scoped to
     `button` for the reason the primary arm is — Avito hangs DS presets on ANCHORS
     too, and those are already claimed by the (0,1,1) `a[class*="styles-module-root"]`
     arm, so a fill rule that loses to it would leave dark ink on a grey chip. */
  button[class*="root_preset_accent-"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  button[class*="root_preset_accent-"],
  button[class*="root_preset_accent-"] * {
    color: #0b1620 !important;
  }
  /* The rest of the Button component's preset vocabulary, all of it natively
     COLOURED and all of it swallowed whole by the generic dark button rule:

       root_preset_success        solid #02D15C — the "показать номер" call CTA on
                                  seller profiles, the green counterpart to the blue
                                  message CTA (see the phone-CTA rules below).
       root_preset_accentSecondary  #cfedff fill + #008AED label — the soft-blue
                                  secondary; every promo/ad card's "Подробнее".
       root_preset_paySecondary   #e9ddfd fill + #8c4fe8 label — the Avito Pay
                                  lavender, used by the cards' "В корзину".

     Each was flattened to the same anonymous `--av-surface` grey as "Написать", so
     an ad CTA, a cart action and a plain secondary all read identically. Keep each
     family's hue but sink the fill to a tinted dark surface, exactly as the
     light-blue phone button is handled. `root_preset_accent` is NOT matched here:
     `[class*=…]` would also catch `root_preset_accentSecondary`. Avito's ad blocks
     ship the same soft-blue CTA under pure-hash classes, so the ad container's
     namespaced wrapper (`avito-ads-container_*`, whose only buttons ARE those
     CTAs) carries the same treatment. */
  button[class*="root_preset_success"] {
    background-color: #198049 !important;
    border-color: #198049 !important;
  }
  button[class*="root_preset_success"],
  button[class*="root_preset_success"] * {
    color: #fff !important;
  }
  [class*="root_preset_accentSecondary"],
  [class*="avito-ads-container"] button {
    background-color: #1d2c3a !important;
    border-color: #2f4a63 !important;
  }
  [class*="root_preset_accentSecondary"],
  [class*="root_preset_accentSecondary"] *,
  [class*="avito-ads-container"] button,
  [class*="avito-ads-container"] button * {
    color: #9fd0f5 !important;
  }
  [class*="root_preset_paySecondary"] {
    background-color: #2b2140 !important;
    border-color: #40325e !important;
  }
  [class*="root_preset_paySecondary"],
  [class*="root_preset_paySecondary"] * {
    color: #c3a3f5 !important;
  }
  /* Avito's ad blocks now build their "Подробнее" CTA from the DS Button's NEUTRAL
     `secondary` preset — a `#f2f1f0` fill with a black label, not the soft-blue
     `accentSecondary` the container arm above was written for — so that arm invented
     a brand tint on twenty CTAs the site paints grey. An explicit preset must outrank
     the container, hence the (0,2,1) pairing. */
  [class*="avito-ads-container"] button[class*="root_preset_secondary"] {
    background-color: #262c35 !important;
    border-color: var(--av-border) !important;
  }
  [class*="avito-ads-container"] button[class*="root_preset_secondary"],
  [class*="avito-ads-container"] button[class*="root_preset_secondary"] * {
    color: var(--av-text-soft) !important;
  }
  /* Design-system BADGE. Both of its presets paint through
     `--module-badge-backgroundColor` (`primary` is the sale red `#ff4053` with a white
     label; `secondary` is a near-black chip, already covered by the preset rule above),
     so the div-neutraliser wipes them — the category mega-menu's "Новое" flag rendered
     as bare grey text with no pill at all.
     `root_preset_primary` is shared with the Button (a `<button>`, promoted to the
     accent above) and the Spinner (a div), so both properties are read from the badge's
     OWN tokens with a fallback: a Spinner leaves them unset and keeps today's flat
     treatment, while a Badge resolves them. Redefining the sale token on the same
     element lands the pill on the refined red the theme uses for every other red fill
     (5.0:1 against the white label) rather than the raw brand hue. */
  div[class*="root_preset_primary"] {
    --theme-semantics-components-badge-bg-sale: #c8323f;
    background-color: var(--module-badge-backgroundColor, transparent) !important;
    color: var(--module-badge-color, var(--av-text-soft)) !important;
  }
  /* Search / company-card "Показать телефон" reveal CTA (marker
     `item-phone-button/undefined`) is natively a SOFT light-blue button
     (#cfedff fill, brand-blue label) — the per-card primary contact action,
     revealed on card hover. The generic button rule greyed it to `--av-surface`,
     which reads grey-on-grey with no affordance against the elevated card. Give
     it a blue-tinted surface + light-blue label so it still reads as the contact
     CTA. The item-page `item-phone-button/header`, `/card` and `/gallery`
     (fullscreen-lightbox footer) primaries are promoted to the solid green call
     CTA by the rules just below (same specificity, later source order wins), so
     this only re-tunes the softer search/card variant. */
  [data-marker^="item-phone-button"] {
    background-color: #1d2c3a !important;
    border-color: #2f4a63 !important;
  }
  [data-marker^="item-phone-button"],
  [data-marker^="item-phone-button"] * {
    color: #9fd0f5 !important;
  }
  /* Primary brand-blue CTAs */
  [data-marker="search-form/submit-button"],
  [data-marker="top-rubricator/all-categories"],
  [data-marker="top-rubricator/all-categories-icon"],
  [data-marker$="/phone-button"],
  button[type="submit"] {
    background-color: var(--av-accent) !important;
    color: #0b1620 !important;
  }
  /* The item page pairs TWO solid primaries: "Показать телефон" is Avito's call
     green `#02D15C` and "Написать" its brand blue `#00AAFF` — the colour is the
     only thing separating a call from a message. The theme painted the phone CTA
     blue and let the messenger anchor fall through to the generic dark button
     rule, so the pair read blue-vs-grey: the call/message distinction was gone and
     the messenger CTA had been demoted to a tertiary. Give each side its own hue
     back, in the tones the theme already uses for green and blue. Same green for
     the profile page's `call-button` (see `root_preset_success` above). */
  [data-marker="item-phone-button/header"],
  [data-marker="item-phone-button/card"],
  [data-marker="item-phone-button/gallery"] {
    background-color: #198049 !important;
    border-color: #198049 !important;
  }
  [data-marker="item-phone-button/header"],
  [data-marker="item-phone-button/header"] *,
  [data-marker="item-phone-button/card"],
  [data-marker="item-phone-button/card"] *,
  [data-marker="item-phone-button/gallery"],
  [data-marker="item-phone-button/gallery"] * {
    color: #fff !important;
  }
  /* `messenger-button/link` is the same marker on BOTH surfaces: a solid brand-blue
     primary on the item page (buy-box + the fixed title bar), and a neutral
     `#f2f1f0` chip on search / profile cards, three to a row. Promote the marker to
     the accent — and put the card variant back, keyed on the fact that it is built
     from the design-system Button (`styles-module-root-…`) while the item page's is
     under pure build hashes. Keying on the DS class rather than on the preset
     modifier matters: the card variant has already shipped as both
     `root_preset_secondary` and `root_preset_overlay`. At (0,2,1) it beats the
     accent rule outright, so no source-order tie is involved. */
  a[data-marker="messenger-button/link"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  a[data-marker="messenger-button/link"],
  a[data-marker="messenger-button/link"] * {
    color: #0b1620 !important;
  }
  a[class*="styles-module-root"][data-marker="messenger-button/link"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  a[class*="styles-module-root"][data-marker="messenger-button/link"],
  a[class*="styles-module-root"][data-marker="messenger-button/link"] * {
    color: var(--av-text-soft) !important;
  }
  /* The model/catalog page's offer rows ship a THIRD build of the same marker, under
     pure build hashes and with no border-radius — natively a plain WHITE square
     secondary sitting under the row's soft-blue "Показать телефон" primary. The DS-class
     arm above cannot reach it, so the accent rule painted it a solid blue slab: the
     loudest thing in the row, square-cornered against its rounded neighbour, and the
     row's two actions ranked upside down. Every card-embedded messenger CTA — search,
     profile, model page — is a `[data-marker="item"]` descendant and is a secondary;
     only the item page's own buy-box copy sits outside a card and stays the accent.
     The fill is the secondary preset's tone, not `--av-surface`: a card only shows this
     CTA while hovered, and the hover panel is itself `--av-surface`, so a surface-
     coloured chip would have no edge at all and read as bare text. */
  [data-marker="item"] a[data-marker="messenger-button/link"] {
    background-color: #262c35 !important;
    border-color: var(--av-border) !important;
  }
  [data-marker="item"] a[data-marker="messenger-button/link"],
  [data-marker="item"] a[data-marker="messenger-button/link"] * {
    color: var(--av-text-soft) !important;
  }

  /* Avito Доставка's delivery CTAs (item page: sticky-header "Купить", buy-box
     "Купить с доставкой" / "В корзину", legacy "Запросить доставку") are natively
     SOLID PURPLE `#965EEB` buttons — the site's delivery accent, and the visual
     counterpart to the blue phone CTA. Their fill comes from a hashed CLASS (not an
     inline style), so none of the `[style*=…]` badge rules above reach them and the
     generic dark `button` surface swallowed them whole: they read as anonymous grey
     tertiary buttons, identical to "Написать". Restore the purple in the same
     refined tone the theme already uses for purple badges (#7d5bc4, 5.0:1 against
     white). The marker was `delivery-item-button-request`; Avito re-split it into
     `-header` / `-main` / `-cart`, so match the whole `delivery-item-button` family
     by prefix (the plain-text `delivery/landing` link has no `-button` and is
     unaffected). The fullscreen photo lightbox ships the same purple CTA under a
     marker outside that family — `gallery-delivery-button` — so it fell through to
     the generic dark button rule and the gallery's only buy action read as an
     anonymous grey pill; the `$=` arm covers it and any future `<surface>-delivery-button`. */
  [data-marker^="delivery-item-button"],
  [data-marker$="-delivery-button"] {
    background-color: #7d5bc4 !important;
    border-color: #7d5bc4 !important;
  }
  [data-marker^="delivery-item-button"],
  [data-marker^="delivery-item-button"] *,
  [data-marker$="-delivery-button"],
  [data-marker$="-delivery-button"] * {
    color: #fff !important;
  }

  /* ---- Segmented filter controls: the SELECTED option ---- */
  /* The search filters ("Состояние": Любое/Новое/Б/у, "Продавцы": Все/Частные/
     Компании) are radio groups whose pill is a SPAN next to a visually-hidden
     checked <input>. Natively the selected pill is a solid BLACK chip with white
     text and the unselected ones are light grey — but the generic button rule
     paints every pill `--av-surface`, and the broad text rule paints every label
     `--av-text-soft`, so all three options rendered IDENTICALLY: the active filter
     was completely invisible. No contrast or luminance check can see this (all the
     chips are legible dark controls); only the native diff shows the lost state.
     Promote the checked pill to the accent, matching the current-page pagination
     pill. */
  input:checked + [class*="style-module-wrapper"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  input:checked + [class*="style-module-wrapper"],
  input:checked + [class*="style-module-wrapper"] * {
    color: #0b1620 !important;
  }

  /* ---- Installment-period selector (item buy-box) ---- */
  /* The "рассрочка" period picker (`installments-promoblock`: 2 / 4 / 5 / 6 мес.)
     is a radio group of `label > input[type=radio] + span` pills. Natively the
     unselected pills are a solid WHITE `#fff` span and the checked one is a
     near-black `#141414` span — but `span` is deliberately left out of the
     div-neutraliser (it carries colour swatches / pagination pills), so the three
     unselected pills stayed bright white, glaring on the dark buy-box. Sink the
     unselected pills to the elevated surface and promote the checked one to the
     accent, matching the segmented filter + pagination selected states above. */
  [data-marker="installments-promoblock"] input[type="radio"] + span {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
    color: var(--av-text) !important;
  }
  [data-marker="installments-promoblock"] input:checked + span {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
    color: #0b1620 !important;
  }
  /* Payment-schedule bar under the same block: the paid segment is green and the
     four upcoming ones are inline `background: rgb(214, 214, 214)` SPANs — a
     subtle track on Avito's white buy-box, but four glaring 53×4 white bars on
     the dark one, louder than the green segment they are supposed to sit behind.
     They are SPANs (outside the div-neutraliser) under pure-hash classes, so the
     inline value is the only stable hook. Sink them to the line colour so the
     green "paid" segment reads as the filled part again. Written against
     `background`, not `background-color`: Avito uses the shorthand here. */
  [style*="background: rgb(214, 214, 214)"],
  [style*="background:rgb(214, 214, 214)"],
  [style*="background:#D6D6D6"], [style*="background:#d6d6d6"] {
    background-color: var(--av-border) !important;
  }

  /* ---- Item-page variant chips (condition / memory / …) ---- */
  /* The item page's attribute switchers ("Расширенное состояние": Отличное /
     Хорошее / Удовлетворительное; "Встроенная память": 128 ГБ / 256 ГБ; "Ещё N")
     are a `[data-marker="multi-items"]` group of `label > input + span` pills.
     Each pill span is a hard-coded light `#f2f1f0` — a different class from the
     `style-module-wrapper` segmented filters above, so none of those rules reached
     it: the broad text rule inked the labels `--av-text-soft` light-grey, leaving
     light-grey text on a light-grey pill (~1.3:1, effectively invisible) and the
     checked pill indistinguishable from the rest. Sink the pills to the elevated
     surface and promote the checked one to the accent, matching the segmented +
     installment selected states. Scoped to the `multi-items` container so the
     separate colour-swatch chips (which carry their hue on the pill) are untouched. */
  [data-marker="multi-items"] label > span {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [data-marker="multi-items"] label > span,
  [data-marker="multi-items"] label > span * {
    color: var(--av-text) !important;
  }
  [data-marker="multi-items"] label input:checked + span {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [data-marker="multi-items"] label input:checked + span,
  [data-marker="multi-items"] label input:checked + span * {
    color: #0b1620 !important;
  }

  /* ---- Model / catalog page (…/catalog/<brand>/<model>/…/specs-…) ---- */
  /* Reached from an item page's "Все характеристики" link. Its modification
     switcher ("Состояние", "Объём памяти", …) is the multi-items pill pattern
     under a DIFFERENT hook — `label > input[type=checkbox] + span` inside
     `model-card/modification-form`, with no `multi-items` marker — so none of the
     rules above reached it: every unselected pill stayed a hard `#f2f1f0` white
     with the broad text rule's light-grey label on top (~1.5:1, unreadable), and
     the checked pill's native `#141414` made it read as the DIMMEST of the group,
     inverting the indicator. Same treatment as every other switcher in the theme. */
  [data-marker="model-card/modification-form"] label > span {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [data-marker="model-card/modification-form"] label > span,
  [data-marker="model-card/modification-form"] label > span * {
    color: var(--av-text) !important;
  }
  [data-marker="model-card/modification-form"] label input:checked + span {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [data-marker="model-card/modification-form"] label input:checked + span,
  [data-marker="model-card/modification-form"] label input:checked + span * {
    color: #0b1620 !important;
  }
  /* The same page's two CTAs are anchors under pure-hash classes, so neither the
     `styles-module-root` nor the `-button` arms above reach them: the secondary
     "Ещё N объявлений" kept its native `#f2f1f0` fill (a bright white 169×44 slab)
     and the primary "Показать N объявлений" — natively a solid `#141414` pill —
     lost its fill entirely and rendered as bare text. */
  [data-marker="model-card/mini-serp-2/button"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* `a[data-marker$="-button"]` (the text-link un-painter above) also matches
     `model-card/ui-button` at (0,1,1), so this arm must carry the `a` type too —
     the tie then breaks on source order. */
  a[data-marker="model-card/ui-button"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [data-marker="model-card/ui-button"],
  [data-marker="model-card/ui-button"] * {
    color: #0b1620 !important;
  }

  /* ---- Item-page colour-variant swatches (inline-rgb solids) ---- */
  /* Each colour option under `[data-marker="multi-item-image"]` is a 48×48 <div>
     whose hue is EITHER a `rect_*_96.png` background-IMAGE (metallics — gold,
     silver — which survive because the div-neutraliser only clears background-
     COLOR) OR an inline solid `background-color: rgb(...)` (deep-purple, graphite/
     black). The neutraliser flattened the solid ones to transparent, so those
     variants rendered as an empty dark square with no hue — an invisible,
     unidentifiable colour option leaving a gap between the metallic chips.
     Restore the inline hue verbatim; scoped to the swatch container so nothing
     structural is touched. Colour list follows Avito's solid product-swatch
     palette (metallics never reach here — they carry a PNG); each hue must be named
     literally, because nothing in CSS can re-apply an inline value an `!important`
     rule has already beaten. On a phone listing offering белый / зелёный / красный /
     синий / чёрный only the last was covered, so four of the five options rendered
     as bare boxes and three of them — having no border either — were completely
     invisible: the picker showed one chip where the site draws five. Both `rgb()`
     spellings are listed for the reason the badge rules list them (a server-rendered
     load and a client re-render serialise the same inline value differently).

     The hues below are Avito's own swatch DICTIONARY, read off the search-filter
     colour picker (`color-circle-circle`, which spells the same values as
     `background:#HEX`) rather than guessed: an iPhone listing offering голубой /
     жёлтый / зелёный / розовый / чёрный still rendered three of the five blank
     because only two of its hues were named here. Any hue NOT in this list renders
     as an empty slot — harvest it from a filter rail and add it; a guessed literal
     is dead code. Metallics (silver, gold) never need naming: they arrive as a
     gradient or a PNG, and the neutraliser only clears background-COLOR. */
  [data-marker="multi-item-image"] [style*="background-color: rgb(106, 54, 227)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(106, 54, 227)"] {
    background-color: rgb(106, 54, 227) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(41, 41, 41)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(41, 41, 41)"] {
    background-color: rgb(41, 41, 41) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 255, 255)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 255, 255)"] {
    background-color: rgb(255, 255, 255) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(28, 140, 56)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(28, 140, 56)"] {
    background-color: rgb(28, 140, 56) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(245, 64, 67)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(245, 64, 67)"] {
    background-color: rgb(245, 64, 67) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(50, 100, 250)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(50, 100, 250)"] {
    background-color: rgb(50, 100, 250) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(28, 191, 255)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(28, 191, 255)"] {
    background-color: rgb(28, 191, 255) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 228, 51)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 228, 51)"] {
    background-color: rgb(255, 228, 51) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 161, 234)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 161, 234)"] {
    background-color: rgb(255, 161, 234) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(156, 156, 156)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(156, 156, 156)"] {
    background-color: rgb(156, 156, 156) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(128, 92, 58)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(128, 92, 58)"] {
    background-color: rgb(128, 92, 58) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(199, 28, 59)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(199, 28, 59)"] {
    background-color: rgb(199, 28, 59) !important;
  }

  /* ---- Text ---- */
  /* The site hardcodes near-black text colours; force them light. */
  body, p, span, li, td, th, div, label, dd, dt, time, small, b, strong, em,
  h1, h2, h3, h4, h5, h6 {
    color: var(--av-text-soft) !important;
  }
  /* Seller business-hours status ("Закрыто до завтра" when closed) is a bare <p>
     whose colour arrives as an inline `color: rgb(255, 97, 99)` — Avito's status
     red. The broad text rule's `!important` beat the inline value and flattened it
     to body grey, erasing the closed/open signal (a colour audit is blind to it:
     the rendered grey reads as ordinary metadata). Preserve the red; native #ff6163
     already clears 4.5:1 on the dark surfaces, so keep the exact hue. Same
     inline-`[style]` lever the badge/ribbon colours use above. */
  [style*="color: rgb(255, 97, 99)"], [style*="color:rgb(255, 97, 99)"],
  [style*="color:#ff6163"], [style*="color:#FF6163"] {
    color: #ff6163 !important;
  }
  /* SEO geo-links tab strip at the foot of a results page. Two tabs mark the
     current one with a bold black `<strong>` and the other with an inline
     `color: rgb(0, 153, 247)` on a bare SPAN — the link blue is the ONLY thing
     saying the second tab is clickable. The broad span rule flattened it to body
     grey, so both tabs rendered identically and the affordance was gone. Same
     inline-`[style]` lever the badge colours use; the theme accent replaces the
     native blue for the same reason `a` does. */
  [style*="color: rgb(0, 153, 247)"], [style*="color:rgb(0, 153, 247)"],
  [style*="color:#0099f7"], [style*="color:#0099F7"] {
    color: var(--av-accent) !important;
  }
  /* Discount-percentage label ("−5%", "−10%") on recommendation / search cards
     is a bare <span data-marker="discount-value"> whose native colour is Avito's
     discount red `#f71b47` (arriving as an inline `color:` and via a class). The
     broad span text rule's `!important` flattened it to body grey, erasing the
     discount signal (a colour audit reads the grey as ordinary price metadata).
     Native #f71b47 clears 4.5:1 on the dark surfaces, so keep the hue. */
  [data-marker="discount-value"],
  [data-marker="discount-value"] * {
    color: #f71b47 !important;
  }
  /* Seller-rating STARS. Each star is a mask-image `<svg>` inside a
     `styles-module-star-…` wrapper: the glyph is painted by the svg's
     `background-color: currentColor`, so the star's colour IS its inherited
     `color`. The broad span rule flattened all 248 of them on a search page from
     Avito's rating gold `#ffb021` to body grey — every seller looked unrated, and
     no contrast or light-surface check can see it (a grey star on a dark card is
     a perfectly legible glyph). Scoped to the star wrapper's `filled` modifier so
     an empty star keeps its muted state. */
  [class*="styles-module-star"] [class*="styles-module-filled"] {
    color: #ffb021 !important;
  }
  /* The ITEM page ships the same rating widget from a newer build whose classes
     are pure hashes, so the `styles-module-filled` hook above misses it and all
     five of the seller's stars rendered body grey — the shop next to "4,9" looked
     unrated. The widget declares its palette as inline custom properties on
     `[data-marker="sellerRate"]` (`--star-color-filled:#ffb021`,
     `--star-color-empty:#e0e0e0`) and picks between them with three hashed classes
     on the star's span; that hash is the ONLY thing separating a filled star from
     an empty one, so it has to be named. Written to fail SAFE: matching the FILLED
     hash means a rebuilt hash drops the stars back to the theme's neutral grey,
     where they are merely uninformative — never gold on an empty star, which would
     overstate a seller's rating. The model/catalog page's offer rows mount the same
     widget under a different marker (`seller-rating/rating-stars`, one `star-N` div
     per star) and were missed by the `sellerRate` scope, so all fifteen stars in its
     offer list rendered body grey — every shop in the list looked unrated. */
  [data-marker="sellerRate"] span[class*="_4da9fca36a8c49c9"],
  [data-marker^="seller-rating/rating-stars"] span[class*="_4da9fca36a8c49c9"] {
    color: #ffb021 !important;
  }
  /* `[data-marker*="title"]` was too loose: Avito also hangs a bare
     `data-marker="title"` on the top notification banner's "Подробнее" LINK — a
     natively brand-blue CTA — so this rule (0,1,0) beat `a { color: accent }`
     (0,0,1) and rendered the banner's only call-to-action as plain body text.
     Listing titles all carry `item-title`; the item page's own H1 is covered by
     the element arm above. */
  h1, h2, h3, h4, h5, h6,
  [class*="title"], [data-marker*="item-title"] {
    color: var(--av-text) !important;
  }

  /* ---- Links / accent ---- */
  a {
    color: var(--av-accent) !important;
  }
  a:hover {
    color: var(--av-accent-hover) !important;
  }
  /* Titles that are links should stay light, not blue. Scoped to `item-title`
     for the same reason as the rule above — a bare `title` marker is also used
     for the notification banner's blue CTA link. */
  a[class*="title"], a[data-marker*="item-title"],
  [data-marker="item-title"] a, h3 a {
    color: var(--av-text) !important;
  }
  [data-marker="item-title"] a:hover, h3 a:hover {
    color: var(--av-accent-hover) !important;
  }
  /* The home grid's listing titles are Link components with `data-marker="title"`
     (not `item-title`, which only search uses) and the design-system's
     `root_preset_black` modifier — natively BLACK body text, not a blue link. The
     generic `a` rule painted all 91 of them brand-blue, so the whole grid read as a
     wall of saturated links and disagreed with the same titles on search, which are
     light. The preset name states the native colour, so keying off it is exact. */
  a[class*="root_preset_black"] {
    color: var(--av-text) !important;
  }
  a[class*="root_preset_black"]:hover {
    color: var(--av-accent-hover) !important;
  }
  /* Avito's design-system Link marks hover by COLOUR alone (`--kitty-link-color-hover`,
     the palette's red600), and its label is a nested Text element — a `<p>` for the
     header's region picker, `<span>`s for the results page's "Сортировка" and
     "Уведомлять о новых". The broad text rule above nails those with `!important`, so
     `a:hover` recoloured the anchor while the visible words never moved: those controls
     had NO hover affordance at all, rest and hover rendering pixel-identical. Carry the
     cue onto the label. The child combinator is load-bearing, not tidiness: a
     seller-name link wraps its whole rating widget, whose gold stars are painted through
     `color`, and a descendant selector would out-specify the star rule and turn every
     star blue on hover — only the label is ever a direct `p`/`span` child. */
  a[class*="root_underlineOffset"]:hover > p,
  a[class*="root_underlineOffset"]:hover > span {
    color: var(--av-accent-hover) !important;
  }

  /* ---- Text on coloured surfaces (must come after the broad text rule) ---- */
  /* Keep labels readable on the re-painted chips, pills and primary buttons. */
  [style*="background-color: rgb(255, 64, 83)"],
  [style*="background-color: rgb(255, 64, 83)"] *,
  [style*="background-color: rgb(2, 209, 92)"],
  [style*="background-color: rgb(2, 209, 92)"] *,
  [style*="background-color: rgb(150, 94, 235)"],
  [style*="background-color: rgb(150, 94, 235)"] *,
  [style*="background-color: rgb(229, 9, 101)"],
  [style*="background-color: rgb(229, 9, 101)"] *,
  [style*="background-color:#FF4053"], [style*="background-color:#FF4053"] *,
  [style*="background-color:#02D15C"], [style*="background-color:#02D15C"] *,
  [style*="background-color:#965EEB"], [style*="background-color:#965EEB"] *,
  [style*="background-color:#E50965"], [style*="background-color:#E50965"] * {
    color: #fff !important;
  }
  [style*="background-color: rgb(0, 170, 255)"],
  [style*="background-color: rgb(0, 170, 255)"] *,
  [style*="background-color:#00AAFF"], [style*="background-color:#00AAFF"] * {
    color: #0b1620 !important;
  }
  [style*="background-color: rgb(204, 236, 255)"],
  [style*="background-color: rgb(204, 236, 255)"] *,
  [style*="background-color: rgb(207, 237, 255)"],
  [style*="background-color: rgb(207, 237, 255)"] *,
  [style*="background-color:#CCECFF"], [style*="background-color:#CCECFF"] *,
  [style*="background-color:#CFEDFF"], [style*="background-color:#CFEDFF"] * {
    color: #9fd0f5 !important;
  }
  /* Dark text only on the brand-blue CTAs. The item page's own green call CTAs
     (`item-phone-button/header|card|gallery`) take white ink from their own rules
     above and must NOT be listed here — this block is later in source order and
     would win the tie. */
  [data-marker="search-form/submit-button"],
  [data-marker="search-form/submit-button"] *,
  [data-marker="top-rubricator/all-categories"],
  [data-marker="top-rubricator/all-categories"] *,
  [data-marker$="/phone-button"],
  [data-marker$="/phone-button"] * {
    color: #0b1620 !important;
  }
  /* "В корзину" is the DS `paySecondary` preset: an `#e9ddfd` lavender fill with an
     `#8c4fe8` label. The generic button surface plus the broad text rule left it an
     anonymous grey CTA; the preset rule above restores the tinted fill, and this
     keeps the purple label at a tone that clears 4.5:1 on it. */
  [data-marker="cart-actions/cart-button"],
  [data-marker="cart-actions/cart-button"] * {
    color: #a97cf0 !important;
  }
  /* Every `button[type="submit"]` is painted brand-blue by the button rules, but
     the label lives in a `<span>` that the broad text rule painted `--av-text-soft`
     — light grey on light blue (~2:1). The auth popup's "Войти" was effectively an
     unreadable CTA. Ink the label like every other brand-blue CTA. */
  button[type="submit"] * {
    color: #0b1620 !important;
  }
  /* The legacy error/404 template ships two anchors styled as brand-blue buttons
     (`header-add-item-link`, `content-home-link`). They carry a native `#00aaff`
     fill and a white label — but `a { color: var(--av-accent) }` repainted the
     label brand-blue on brand-blue, so both CTAs read as empty pills. */
  a.header-add-item-link, a.content-home-link {
    background-color: var(--av-accent) !important;
  }
  a.header-add-item-link, a.header-add-item-link *,
  a.content-home-link, a.content-home-link * {
    color: #0b1620 !important;
  }

  /* ---- Inputs, selects, filter fields ---- */
  [data-marker="search-form/suggest/input"],
  [data-marker="search-form"] input,
  input, textarea, select,
  [data-marker$="/multiselect-outline-input"],
  [data-marker$="-from"], [data-marker$="-to"],
  [class*="multiselect"], [class*="-input"], [class*="Input"] {
    background-color: var(--av-surface) !important;
    color: var(--av-text) !important;
    border-color: var(--av-border) !important;
  }
  /* The search field sits in a white wrapper — darken that too. */
  [data-marker="search-form/suggest"] {
    background-color: var(--av-surface) !important;
  }
  /* Focusing the header search opens the suggest widget, which paints its
     expanded panel (the sheet the input and the suggestion list sit on) with a
     hard-coded white `::before` — a pseudo-element, so every element-bg scan
     reports the page clean while a white ring/sheet flashes around the input. */
  [class*="index-suggest"]::before,
  [class*="index-form"] [class*="index-button"]::before {
    background-color: var(--av-surface) !important;
  }
  ::placeholder { color: var(--av-text-muted) !important; opacity: 1; }
  /* Every row of that suggest panel is prefixed by a 20×20 `<img>` from Avito's
     suggest icon set (`/s/a/i/suggest/*.png`, `/s/suggest/<category>/*.png`,
     `/static/ims/…_suggest_with_query_light_80x80.png`) — flat BLACK line art drawn
     for the native white sheet, so on the dark panel every row led with an
     invisible glyph. A raster's pixels are out of reach of `fill`/`color`, so flip
     the lightness; the whole set is monochrome (the "full_color" path name
     notwithstanding), so an invert cannot distort a hue. Scoped to the icon's own
     class, which is the only node in the panel that is an `<img>`. */
  [class*="itemIconImg"] {
    filter: invert(1);
  }

  /* Auth popup (login + registration). Its fields were a grey rectangle on the
     white modal; the neutraliser wiped that fill, and the generic input rule
     above then painted them `--av-surface` — exactly the popup's own colour, so
     an unfocused field (e.g. "Пароль") was invisible: only its placeholder
     floated in mid-air. Sink the fields back to the base canvas so they read as
     inputs against the elevated popup. */
  [data-marker="auth-app/popup"] input {
    background-color: var(--av-bg) !important;
  }

  /* ---- Checkbox / radio checked state ---- */
  /* The real control is a DIV painted next to a visually-hidden <input>, and its
     checked fill comes from `--kitty-commonToggle-toggle-checked-background` on
     that DIV — which the div neutraliser wiped. Result: a ticked filter box was
     indistinguishable from an empty one (dark box, grey tick) instead of the
     brand-blue fill. Restore the fill and darken the tick/dot (drawn with
     `fill: currentColor`, so it follows `color`). Scoped to checkbox/radio mode
     so switch controls keep their own knob styling. */
  [class*="controlledInput_checked"] + [class*="toggle_mode_checkbox"],
  [class*="controlledInput_checked"] + [class*="toggle_mode_radio"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [class*="controlledInput_checked"] + [class*="toggle_mode_checkbox"],
  [class*="controlledInput_checked"] + [class*="toggle_mode_checkbox"] *,
  [class*="controlledInput_checked"] + [class*="toggle_mode_radio"],
  [class*="controlledInput_checked"] + [class*="toggle_mode_radio"] * {
    color: #0b1620 !important;
  }

  /* ---- Switch (toggle) track ---- */
  /* The switcher's track is a DIV the neutraliser flattened to transparent, so
     both states rendered as a white knob floating on the page with no track at
     all: natively the track is light `#e3e2e1` when off and near-black `#141414`
     when on, and it is the ONLY thing that distinguishes the two beyond a 20px
     knob shift. Give the off state a visible neutral rail and the on state the
     accent, matching every other "selected" indicator in the theme. */
  [class*="toggle_mode_switcher"] {
    background-color: var(--av-border) !important;
  }
  [class*="controlledInput_checked"] + [class*="toggle_mode_switcher"] {
    background-color: var(--av-accent) !important;
  }

  /* ---- Search results view-mode switcher (list / gallery / map) ---- */
  /* Avito marks the ACTIVE view by colour alone: the current icon is near-black
     `#000` and the other two are muted `#757575`. The active one is a DIV (so the
     broad text rule greyed it) while the others are `<a>` (so `a { accent }`
     turned them bright blue) — the indicator ended up exactly INVERTED, the
     selected view reading as the dimmest of the three. The two inactive icons are
     mask-image glyphs painted from `currentColor`, so `color` carries them; the
     active one ships an inline `--kitty-icon-color: #000000`, so its glyph is a
     hard black `background-color` that no `color` rule can reach — it needs the
     background painted directly. */
  [data-marker^="view-change"] {
    color: var(--av-text-muted) !important;
  }
  [data-marker$="/icon-active"] {
    color: var(--av-accent) !important;
    background-color: var(--av-accent) !important;
  }

  /* ---- Tab bars (seller profile: Главная / Объявления / Отзывы) ---- */
  /* Natively these are transparent `<button>`s that mark the current tab by TEXT
     COLOUR alone — active `#000`, the rest `#757575`. Two of our broad rules
     erased that: the generic button rule gave each one an `--av-surface` pill
     (so the whole strip read as one grey slab against a natively bare row), and
     the label carries a `…tab-button-title-…` class, so `[class*="title"]` inked
     every label `--av-text` and the active tab became indistinguishable from the
     other two. Restore the bare row and re-encode the state as muted vs accent.
     The title arms are (0,2,0) so they outrank the generic title rule; the active
     arm ties them and wins on source order. */
  [class*="tab-button"] {
    background-color: transparent !important;
  }
  [class*="tab-button"],
  [class*="tab-button"] [class*="tab-button-title"] {
    color: var(--av-text-muted) !important;
  }
  [class*="tab-button_active"],
  [class*="tab-button_active"] [class*="tab-button-title"] {
    color: var(--av-accent) !important;
  }

  /* ---- Floating surfaces (dropdowns, popovers, menus) ---- */
  /* These are DIV-based, so the neutraliser above wiped their backgrounds and
     page content bled through (search autocomplete, sort menu, region picker,
     "Ещё" nav menu). Re-establish an opaque elevated surface on every floating
     panel via stable data-marker / class-prefix selectors. */
  [data-marker="suggest/list/dropdown"],
  [class*="suggest-dropdownItems"],
  [class*="styles-module-dropdown"],
  [class*="styles-module-dropdownScrollWr"],
  [class*="styles-module-popup"],
  [class*="styles-module-popover"],
  [class*="styles-module-tooltip"],
  [class*="popup-popup"],
  [class*="popover-content"],
  [data-marker="overlay"] [role="listbox"],
  [role="listbox"], [role="menu"], [role="tooltip"], [role="dialog"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* `role="listbox"` above is a floating-panel hook, but Avito's design-system List
     component also hangs the role on IN-FLOW horizontal carousels — the seller
     profile's "Группы объявлений" (`item_selections/items-list`) and the category
     hub's stories rail — so the panel fill stamps an elevated slab behind them that
     the site never draws and that ends abruptly at the carousel's scroll edge.
     Orientation is the durable discriminator: a floating dropdown listbox is vertical.
     The ARIA arm is the general one — the item page's "Другие объявления компании" rail
     (`i2i-carousel`) carries the role and the orientation but neither the DS class nor
     the `/items-list` marker. All three arms outrank the (0,1,0) panel arm. */
  [role="listbox"][aria-orientation="horizontal"],
  [role="listbox"][class*="_orientation_horizontal"],
  ul[data-marker$="/items-list"] {
    background-color: transparent !important;
  }
  /* Header nav fly-out menus ("Ещё", "Для бизнеса", "Каталоги") — hashed-class
     absolutely-positioned panels nested in the nav. Stable hook: the
     nav-container-HEADER wrapper. Each such `li` holds exactly two child divs — the
     TRIGGER (link + caret, natively transparent) then the PANEL — so the adjacent-
     sibling combinator selects the panel alone. Without it the trigger also took an
     `--av-surface` fill, giving "Для бизнеса" and "Ещё" a grey pill that read as an
     active/selected state their plain-link siblings never got. */
  [class*="nav-container-HEADER"] li > div > div + div {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* Category RUBRICATOR mega-menu — the panel behind the blue grid button next to the
     logo, on every page type. Its 1280×528 sheet is a natively WHITE pair of nested
     DIVs (`new-rubricator-content-root` / `…root_wrapper` / `…root_content`), and the
     div-neutraliser flattened all of them: the whole category tree rendered straight
     over the page underneath, headings and links stacked on top of the results grid
     and unreadable. Painting the shared `…content-root` prefix covers all three nested
     nodes at once; they are opaque over opaque in the same tone, so the nesting is
     harmless. No load-time scan sees this — the panel is portalled in on click. */
  [class*="new-rubricator-content-root"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* Its wrapper is the menu's backdrop (natively `rgba(0,0,0,0.32)`) — see the portal
     backdrop rule further down, which covers it and the item page's dialog scrim in
     one arm. Inside it, the root-category list marks which subtree is on show with a light
     `#f2f1f0` fill on the current row and nothing else — no icon, no ink change — so
     the neutraliser left all twelve rows identical. The `active` modifier is the only
     discriminator; a raised surface reads the same way the light fill does natively. */
  [data-marker^="top-rubricator/root-category"][class*="styles-module-active"] {
    background-color: #262c35 !important;
  }
  /* And its promo card is a `#cfedff` light-blue panel, the same soft blue the theme
     sinks to a tinted dark chip everywhere else. Scoped to the open menu so the shared
     `background_color` class is untouched elsewhere. */
  [data-marker="more-popup"] [class*="styles-module-background_color"] {
    background-color: #1d2c3a !important;
  }
  /* Third-party UX-survey card ("Сейчас мы изучаем, как люди пользуются Авито",
     `position: fixed`, bottom-right). Every node in the widget is a DIV under the
     `uxs-` namespace, so the neutraliser blanked the whole card: its heading and
     CTA rendered straight over the listing grid behind it, unreadable. The class
     hashes rebuild but the `uxs-` prefix is the vendor namespace and cannot
     collide with Avito's own (`styles-module-…`, `index-…` or a pure-hex hash).
     Painting every node the same surface is equivalent to painting the card, so
     no inner wrapper needs to be singled out; the CTA is natively `#00aaff` and
     is promoted back out of that fill. */
  [class*="uxs-"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [class*="uxs-"] button {
    background-color: var(--av-accent) !important;
  }
  [class*="uxs-"] button,
  [class*="uxs-"] button * {
    color: #0b1620 !important;
  }
  /* The card's dismiss control is the widget's only `type="button"` — its submit CTA
     carries no `type` — and it is bare chrome: a 20×20 icon-only button with no fill
     of its own, holding an `<svg>` whose path has a hard `fill="#B5B8C2"`. The accent
     rule above must not reach it, and its `color` is reset so a build that switches the
     glyph to `currentColor` still renders it light rather than near-black. */
  [class*="uxs-"] button[type="button"] {
    background-color: transparent !important;
  }
  [class*="uxs-"] button[type="button"],
  [class*="uxs-"] button[type="button"] * {
    color: var(--av-text-soft) !important;
  }
  /* The card's Avito wordmark is an `<img>` of a black-on-transparent SVG, and the
     vendor watermark below the CTA is a mask-image glyph painted by its own
     background — both vanished on the dark card (the wordmark literally black on
     near-black). An `<img>`'s pixels are out of reach of `fill`/`color`, so flip
     its lightness and rotate the hue back, which whitens the lettering while the
     four brand dots keep their colours. */
  [class*="uxs-"] img {
    background-color: transparent !important;
    filter: invert(1) hue-rotate(180deg);
  }
  [class*="uxs-"] a div {
    background-color: var(--av-text-muted) !important;
  }
  /* Cookie-consent toast (bottom-centre, z-index 12000). It is a DIV-based
     floating "kitty toastBar", so the neutraliser flattened it to transparent
     and its text rendered straight over the listing photos behind it. */
  [data-marker="cookie-consent"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* Modal backdrop scrim (region picker, auth popups, …). Avito paints it with
     `--kitty-backdrop-background` on a DIV, which the neutraliser wiped — the
     dialog then floated with no separation from the page behind it. Only the
     `<name>/overlay` markers are backdrops; the bare `overlay` marker wraps
     dropdown listboxes and must stay transparent. */
  [data-marker$="/overlay"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  /* Portalled backdrops that carry no marker of their own: the item page's dialogs
     ("Причина жалобы") hang theirs on a `position:fixed` wrapper under pure build
     hashes, and the header's category mega-menu wrapper is the same shape. Both were
     wiped by the neutraliser, so an open dialog floated over a page at full brightness
     and the mega-menu had nothing behind it at all. `role="region"` is the stable hook.
     The child combinators are load-bearing, NOT decoration: the mega-menu's own inner
     panel carries the same role several levels deeper, and a descendant selector at
     (0,2,0) beat the `new-rubricator-content-root` surface above and washed the open
     menu 40% black. Only a backdrop sits two levels under the portal container. */
  [data-marker="portals-container"] > div > [role="region"] {
    background-color: rgba(0, 0, 0, 0.4) !important;
  }
  /* Suggestion / menu rows stay readable on the panel. */
  [data-marker="suggest/list/custom-option"],
  [data-marker="suggest/list/custom-option"] * {
    color: var(--av-text-soft) !important;
  }
  [data-marker="suggest/list/custom-option"]:hover {
    background-color: var(--av-surface-2) !important;
  }
  /* Popover / tooltip arrow. Avito draws the nub as a rotated DIV whose fill is
     its `background-color`; the neutraliser wiped it and the `*` border rule then
     outlined the empty box, so the region popover pointed at nothing with a small
     hollow grey ring hovering above it. Match the panel it belongs to. */
  [class*="styles-module-point-"],
  [class*="styles-module-point_"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-surface) !important;
  }
  /* Page dimmer behind the expanded header-search suggest. It is `display:none`
     while closed, so restoring its fill cannot leak onto the resting page. */
  [class*="index-blackout"] {
    background-color: rgba(0, 0, 0, 0.5) !important;
  }
  /* Full-screen photo lightbox. Its 0.7-black backdrop lives on two hashed DIVs
     that carry no marker and no stable class, and the only ancestor hook is the
     unnamed portal node — so the neutraliser blanked it and the whole item page
     stayed visible behind the opened photo. A parent-selector rule would reach the
     backdrop but is stripped from the userstyles.org build, so paint the scrim from
     a fixed `::before` hung on the one marker'd descendant instead: `position:fixed` sizes
     it to the viewport and `z-index:-1` drops it behind the gallery's own chrome
     while staying inside the portal's stacking context. */
  [data-marker="extended-gallery/frame-wrapper"]::before {
    content: "";
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: -1;
    background-color: rgba(0, 0, 0, 0.85) !important;
  }

  /* ---- Dark scrims over photos (erased by the div-neutraliser) ---- */
  /* Avito floats white icons and white labels directly on listing photos and
     relies on a translucent BLACK pill behind each one for legibility (values
     read from the site's own stylesheet). The neutraliser flattened every one of
     those pills, so a white delivery glyph or a "Просмотрено" label landed on a
     bare photo and vanished against any light image. Restore the scrims and keep
     their labels white. */
  [class*="styles-galleryBadge"],
  [class*="photo-slider-item-more"],
  [class*="badge-reserved"],
  [class*="badge-viewed"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  [class*="photo-slider-counter"],
  [class*="custom-badge-module-badge"],
  [class*="delivery-badge-module-deliveryBadge"],
  [class*="favorite-icon-box-module-iconBox"] {
    background-color: rgba(0, 0, 0, 0.45) !important;
  }
  [class*="photo-slider-item-more"],
  [class*="photo-slider-item-more"] *,
  [class*="photo-slider-counter"],
  [class*="badge-reserved"], [class*="badge-reserved"] *,
  [class*="badge-viewed"], [class*="badge-viewed"] * {
    color: #fff !important;
  }

  /* ---- Ad disclosure ---- */
  /* The "Реклама ⋮" tag is the legally required ad marker. Natively a translucent
     WHITE chip with black text over the creative; the neutraliser erased the chip
     and the broad text rule greyed the label, leaving it barely legible on a light
     creative. A translucent BLACK chip with white text reads on any creative. */
  [data-marker="adv-badge-tag"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  [data-marker="adv-badge-tag"],
  [data-marker="adv-badge-tag"] * {
    color: #fff !important;
  }
  /* ---- Design-system Banner ---- */
  /* The Banner paints its card on a child layer (`styles-module-background_color`)
     whose fill is `var(--kitty-banner-backgroundColor)` — a token the preset class on
     the Banner ROOT sets, so no `[style*=…]` or literal-colour selector can reach it and
     the div-neutraliser wipes the card entirely: the banner's heading, fields and CTA
     end up floating on the bare canvas with no card at all.
     The component's whole preset vocabulary is eight names, read off Avito's own
     stylesheet; each is a semantic bg token, so each keeps its hue and sinks to the tone
     the theme already uses for that meaning. `beige`/`warmGray`/`white` are the neutral
     ones and take the plain elevated surface.
     `background-image` must be cleared on the same layer: a caller can hand the card an
     inline stack of pastel `radial-gradient`s (the seller profile's "Лучшие предложения"
     showcase cards ship three of them), which layers over any background-COLOR and left
     those cards near-white with the theme's light-grey ink on top at about 1.2:1. */
  [class*="root_preset_blue"] [class*="styles-module-background_color"] {
    background-color: #1d2c3a !important;
    background-image: none !important;
    border-color: #2f4a63 !important;
  }
  [class*="root_preset_green"] [class*="styles-module-background_color"] {
    background-color: #16291d !important;
    background-image: none !important;
    border-color: #24452e !important;
  }
  [class*="root_preset_red"] [class*="styles-module-background_color"] {
    background-color: #2e1a1d !important;
    background-image: none !important;
    border-color: #4a2a2f !important;
  }
  [class*="root_preset_orange"] [class*="styles-module-background_color"] {
    background-color: #2a2116 !important;
    background-image: none !important;
    border-color: #3d3120 !important;
  }
  [class*="root_preset_violet"] [class*="styles-module-background_color"] {
    background-color: #2b2140 !important;
    background-image: none !important;
    border-color: #40325e !important;
  }
  [class*="root_preset_beige"] [class*="styles-module-background_color"],
  [class*="root_preset_warmGray"] [class*="styles-module-background_color"],
  [class*="root_preset_white"] [class*="styles-module-background_color"] {
    background-color: var(--av-surface) !important;
    background-image: none !important;
    border-color: var(--av-border) !important;
  }
  /* The Beduin Gradient component (promo strips such as the vacancies hub's "В отпуск
     перед новой работой") paints a pastel `linear-gradient` as its background-IMAGE, fed
     by an inline `--beduin-gradient`. The div-neutraliser only clears background-COLOR,
     so the strip stayed near-white while the broad text rule inked its heading and
     subtitle light grey — around 1.3:1. Both the component class and the token are
     matched so either spelling reaches it. */
  [class*="Gradient-module-root"],
  [style*="--beduin-gradient"] {
    background-image: none !important;
    background-color: var(--av-surface) !important;
  }
  /* Partner promo card on the item page ("Получите кешбэк от Альфа‑Банка"): a soft-red
     `#ffe0e0` panel whose fill arrives as an inline `background:` SHORTHAND on a
     hash-classed div, so no class hook and no `background-color:` selector reaches it
     and the div-neutraliser wiped the card outright — heading, body and CTA floated on
     the bare canvas with no panel behind them. Takes the same red-tinted surface as the
     Banner's `red` preset. Both `rgb()` spellings and both hex cases are listed for the
     reason the badge rules list them. */
  [style*="background: rgb(255, 224, 224)"],
  [style*="background:rgb(255, 224, 224)"],
  [style*="background:#FFE0E0"], [style*="background:#ffe0e0"] {
    background-color: #2e1a1d !important;
    border-color: #4a2a2f !important;
  }

  /* ---- Model-rating badge (item page) ---- */
  /* The green `#00c257` score pill next to "N отзывов о модели" is a hashed DIV
     the neutraliser flattened, leaving a bare grey "4,7". Its only stable hook is
     the `rating-and-reviews` marker two levels up. */
  [data-marker="rating-and-reviews"] > div > div:first-child > div,
  [data-marker="rating-and-reviews"] > div > div:first-child > div * {
    color: #fff !important;
  }
  [data-marker="rating-and-reviews"] > div > div:first-child > div {
    background-color: #198049 !important;
  }
  /* The "138 отзывов о модели" label beside that pill is the LINK to the model's
     reviews — the whole block is wrapped in an `<a>` whose native colour is the
     rating green `#00a34c`. The label is a bare SPAN, so the broad text rule
     (`span { color: --av-text-soft }`) beat the anchor and painted it plain body
     grey: the review count lost both its green and any hint of being clickable.
     Lift the green instead of blueing it, keeping it tied to the score pill. The
     "4,7" inside the pill stays white — the rule above is more specific. */
  [data-marker="rating-and-reviews"] span {
    color: #57c98a !important;
  }
  /* The MODEL / catalog page shows the same score-and-reviews block under its own
     marker, and both halves were lost there: the review-count link flattened to body
     grey, and the pill's fill wiped by the div-neutraliser so the score read as a bare
     grey number with nothing marking it as a rating at all. */
  [data-marker="model-card/common-info/rating"] span {
    color: #57c98a !important;
  }
  /* That pill takes its fill from an INLINE design token rather than a class or a
     literal colour (`background-color: var(--theme-semantics-components-rate-bg-*)`),
     so no `[style*="rgb(…)"]`/`[style*="#hex"]` selector in this file could reach it —
     the token NAME is the hook. Avito's rate palette is a five-step SCALE
     (excellent #00c257, good #72ca00, medium #fca400, low #f71b47, none #999894), and
     collapsing it to one tone would trade a missing pill for a rating that always
     looks the same; each step is named separately and refined to clear 4.5:1 against
     the white label. Listed after the link rule so the score inside the pill stays
     white rather than taking the link's green (equal specificity, later wins). */
  [style*="--theme-semantics-components-rate-bg-excellent"] {
    background-color: #198049 !important;
  }
  [style*="--theme-semantics-components-rate-bg-good"] {
    background-color: #4b7f10 !important;
  }
  [style*="--theme-semantics-components-rate-bg-medium"] {
    background-color: #8a5a00 !important;
  }
  [style*="--theme-semantics-components-rate-bg-low"] {
    background-color: #c8323f !important;
  }
  [style*="--theme-semantics-components-rate-bg-none"] {
    background-color: #4a4f57 !important;
  }
  [style*="--theme-semantics-components-rate-bg-"],
  [style*="--theme-semantics-components-rate-bg-"] span {
    color: #fff !important;
  }

  /* ---- Pagination current page ---- */
  /* Avito marks the current page with a near-black `#141414` pill and white text.
     The neutraliser erased the pill, and restoring the native colour would only
     trade an invisible indicator for a different invisible one on a dark canvas —
     so promote it to the theme's accent. Without this, page 1 is indistinguishable
     from pages 2–5. */
  [data-marker^="pagination-button"][aria-current="page"] {
    background-color: var(--av-accent) !important;
  }
  /* The digit lives in a nested span the broad text rule would otherwise grey. */
  [data-marker^="pagination-button"][aria-current="page"],
  [data-marker^="pagination-button"][aria-current="page"] * {
    color: #0b1620 !important;
  }

  /* ---- Buttons ---- */
  [data-marker="search-form/submit-button"],
  button[type="submit"] {
    background-color: var(--av-accent) !important;
    color: #0b1620 !important;
  }

  /* ---- Hover feedback on painted controls ---- */
  /* Avito's design system marks button, chip and card-CTA hover by swapping a
     background token. Every fill this theme paints is `!important`, so that swap lost
     the cascade on every control at once: buttons, filter chips and the search cards'
     phone/message CTAs all rendered pixel-identical at rest and under the pointer.
     A `brightness()` lift is used instead of per-variant hover fills because the fill a
     control ends up with depends on which of the rules above won it — the accent, the
     call green, the delivery purple, the soft-blue chip and the plain surface each need
     a different hover tone, and a filter derives it from whatever is actually painted.
     It also cannot invent a surface: a natively bare control has nothing to lighten.
     Excluded: `filter` makes an element the containing block for its `position:fixed`
     descendants, so lifting the fixed title bar's favourite button would drag that bar's
     background pseudo out of the viewport and collapse it onto the button's own box. */
  button:hover,
  a[class*="styles-module-root"]:hover,
  [class*="style-module-wrapper"]:hover {
    filter: brightness(1.3);
  }
  .js-item-view-title-info [data-marker="item-view/favorite-button"]:hover {
    filter: none;
  }
  /* Pagination page numbers are natively bare and mark hover with a grey pill, so a
     brightness lift has nothing to act on. The current page carries the accent from the
     rule above and is a `<span>`, so only the other pages match here. */
  [data-marker^="pagination-button"] a:hover {
    background-color: var(--av-surface) !important;
  }

  /* ---- Search-result card hover highlight (pseudo-element panels) ---- */
  /* On card hover Avito paints a full-card light-grey backdrop via
     `.iva-item-redesign…:hover::before` (inset:-8px, rgb(245,245,245)) plus a
     light halo behind the floating action buttons via
     `.iva-item-actions…::before` (box-shadow glow). Both are ::before panels —
     invisible to element-bg scans — and flash bright on every hover. Repaint
     them to the dark elevated surface and drop the light halo shadow. Classes
     are hashed, so hook the stable `iva-item-` prefixes. */
  /* The model/catalog page's offer rows ship the same hover panel under pure-hash
     classes, so the `iva-item-` arms miss it and the whole row went white with
     near-invisible light-grey text on it. Every card that carries the panel is a
     `[data-marker="item"]`, on both surfaces — the marker is the durable hook.
     The pseudo only exists on hover, so painting it unconditionally cannot show a
     surface on a resting card. */
  [class*="iva-item-redesign"]:hover::before,
  [class*="iva-item-redesign"]:hover [class*="iva-item-actions"]::before,
  [class*="iva-item-actions"]::before,
  [data-marker="item"]::before {
    background-color: var(--av-surface) !important;
    box-shadow: none !important;
  }

  /* ---- Carousel scroll-arrow buttons (SVG-disc, audit-blind) ---- */
  /* The "other listings" / recommendation carousels render their round scroll
     buttons as an SVG `<rect fill=#fff>` disc with a black `<path>` arrow — a
     bright white circle glaring on the dark page (element-bg scans miss SVG
     fills). Darken the disc to the elevated surface and lighten the arrow.
     The hub rails' marker-less copy ships the OPPOSITE polarity — a `#141414`
     disc with a white arrow, which collapses into the near-black canvas — so the
     pair is normalised in both directions to the same surface/ink values. */
  [data-marker$="/scroll-button-back"] svg rect,
  [data-marker$="/scroll-button-forward"] svg rect,
  button[class*="styles-module-scrollButton"] svg rect {
    fill: var(--av-surface) !important;
  }
  [data-marker$="/scroll-button-back"] svg path,
  [data-marker$="/scroll-button-forward"] svg path,
  button[class*="styles-module-scrollButton"] svg path {
    fill: var(--av-text) !important;
  }

  /* ---- Gallery thumbnail strip: the SELECTED photo ---- */
  /* Both strips — the item page's inline row (`image-preview/item`) and the fullscreen
     lightbox's rail (`extended-image-preview/item`) — mark the current photo with a
     brand-blue `::after` ring and nothing else, so the blanket `*::after` border reset
     collapses it to the generic line colour and every thumbnail reads the same. The
     pseudo has `content: none` on the unselected thumbnails, so painting it
     unconditionally cannot draw a ring on them. */
  [data-marker="image-preview/item"]::after,
  [data-marker="extended-image-preview/item"]::after {
    border-color: var(--av-accent) !important;
  }

  /* ---- Favorite (add-to-wishlist) heart outline (SVG stroke, audit-blind) ---- */
  /* Search cards and item pages render the un-favourited heart as an SVG whose
     path has NO fill (`fill:none`) and a hard-coded black `stroke` → a near-invisible
     black outline on the dark card. Both the element-bg and the white-fill SVG scans
     miss a stroke-only black icon. Lighten the stroke to a muted grey; the favourited
     state uses a separate filled/red icon and is untouched. */
  [data-marker="favorites-add"] svg path,
  [data-marker="item-view/favorite-button"] svg path,
  [class*="favoritesOutlineIcon"] path {
    stroke: var(--av-text-muted) !important;
  }

  /* ---- Category-hub landing tiles & cards (e.g. /all/bytovaya_elektronika) ---- */
  /* The electronics/category HUB pages render their showcase surfaces as hashed
     `<a>` elements — which the div-only neutraliser above never touches — so they
     keep a hard light-grey fill: the visual-rubricator category tiles, the lazy
     product-image placeholders inside the "Техника Apple"/appliance blocks, and
     the search-history chips. Repaint each to the elevated dark surface. */
  [class*="visual-rubricator-gridItem"],
  [class*="search-history-widget-item"],
  [class*="category-block-img__placeholder"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* One tile per grid is the FEATURED one: the class fill is a neutral `#f2f1f0`, and
     the highlight arrives as an inline soft-blue `background:` shorthand, so the rule
     above flattened it into the row and the grid lost its lead tile. Take the theme's
     soft-blue chip tone. Scoped to the tile class — the search rail's colour swatches
     spell their hue the same way and must keep it verbatim. Both hex cases and both
     `rgb()` spellings are listed: a server-rendered load and a client re-render
     serialise the same inline value differently. */
  [class*="visual-rubricator-gridItem"][style*="background:#cfedff"],
  [class*="visual-rubricator-gridItem"][style*="background:#CFEDFF"],
  [class*="visual-rubricator-gridItem"][style*="background: rgb(207, 237, 255)"],
  [class*="visual-rubricator-gridItem"][style*="background:rgb(207, 237, 255)"] {
    background-color: #1d2c3a !important;
    border-color: #2f4a63 !important;
  }

  /* Stories-rail scroll arrow. It is an empty DIV whose glyph is a background-IMAGE
     (`avito.st/.../*.svg`, a single `stroke="black"` path), so the div-neutraliser —
     which only clears background-COLOR — leaves a black arrow on the dark canvas and
     no `color`/`fill` rule can reach it. The asset is monochrome, so inverting its
     lightness cannot distort a hue. */
  [class*="story-previewer-arrow"] {
    filter: invert(1);
  }

  /* ---- Loading skeletons ---- */
  /* While a result list re-fetches (pagination, sort change, the home grid's lazy
     pages) Avito swaps in `placeholder-one-…` blocks whose bars are drawn by a
     mid-grey SVG served as a background-IMAGE. The div-neutraliser only clears
     background-COLOR, so the artwork survived and a 634×202 light-grey slab
     flashed over the dark page on every reload — and no scan sees it: the element
     background is transparent and the grey is well under the near-white
     threshold. Dimming the layer keeps the skeleton's shape and lands it on the
     elevated-surface tone. */
  [class*="placeholder-one"] {
    opacity: 0.25;
  }
  /* The buyer-pages micro-frontend draws its own hydration skeletons — the home
     recommendation grid, the ad-mimicry cards seeded through it and the side-block
     stub — with a near-white SVG (#F5F5F5 / #EBEAE8 / #FFF artwork) served as a
     background-IMAGE, so the div-neutraliser, which only clears background-COLOR,
     leaves them at full brightness for the second or two before the feed mounts.
     `opacity` is not available as the dimmer here: their pulse ANIMATES opacity, so
     an unimportant value never applies and an important one kills the pulse. The
     artwork is achromatic, so inverting its lightness cannot shift a hue, and 0.86
     lands #F5F5F5 on ~#2b2b2b — a step above the elevated surface.

     The grid skeleton is a hash-only twin of the REAL recommendations grid (same
     `styles-root-`/`styles-compactGrid-`/`styles-main-` shape): the real one carries
     `id="bx_recommendations"` and its cards as children, so both guards are what
     keeps this filter off live listing photos. */
  div[class*="styles-compactGrid-"]:not([id]):empty,
  div[class*="advert-mimicry-block-skeleton"],
  div[class*="placeholder-loading"] {
    filter: invert(0.86);
  }

  /* ---- Price (semantic, kept prominent and light) ---- */
  [data-marker="item-price"],
  [data-marker="item-price-value"],
  [data-marker="item-view/item-price"],
  [itemprop="price"] {
    color: var(--av-text) !important;
  }
  /* Sellers can PAY to highlight a price. Avito paints that yellow swash (#FFD950,
     a single-path avito.st SVG) as a `background-image` on an EMPTY, absolutely
     positioned sibling whose own `background-color` is `transparent` — so the
     element-bg audit sees nothing and the rule above left near-white text sitting
     on bright yellow at 1.16:1. Keep the swash (it is the paid feature) and re-ink
     the text to 13.3:1 instead. The highlighted STATE lives on the price's parent
     (`price-highlightRedesign`); the swash div itself holds no text, so scoping to
     `price-yellowHighlight` would match nothing. */
  [class*="price-highlightRedesign"],
  [class*="price-highlightRedesign"] * {
    color: #0b1620 !important;
    -webkit-text-fill-color: #0b1620 !important;
  }

  /* ---- Footer ---- */
  /* Only the legacy error/404 template ships a real `<footer>`, and there it IS the
     full-width page footer, so it takes the header tone.
     The modern template has no `<footer>` at all: `[data-marker="footer"]` is just the
     1200px CONTENT COLUMN, and the full-width band around it lives on a wrapper under
     pure build hashes. Painting the marker therefore stamped a hard-edged near-black
     slab into the middle of the page — canvas showing 40px either side and 80px below
     it. The band is unreachable, and natively it is `#f7f7f5` against a `#fff` page: a
     3% step with no meaningful dark counterpart, so the column is left on the canvas
     rather than given an edge the site never draws. The `*=` arm still carries the link
     ink, and must not carry a fill — it also matches every descendant marker
     (`footer/regions/seo-link`, `footer/more/toggle`, …), not just the column. */
  footer {
    background-color: var(--av-header) !important;
    border-color: var(--av-border) !important;
  }
  footer a, [data-marker*="footer"] a {
    color: var(--av-text-soft) !important;
  }
  /* The page footer is a `<div data-marker="footer">`; every semantic `<footer>` Avito
     ships inside a dialog is a COMPONENT action row, natively transparent, so the
     element arm above stamps a near-black slab across the panel it sits on. The bare
     arm has to stay — a `<footer>` is outside the div-neutraliser, so dropping it would
     let a natively light one through on a template not covered here. */
  [role="dialog"] footer {
    background-color: transparent !important;
  }
}
